{
  "imports": [
    "from decimal import Decimal",
    "import pytest",
    "from ledger.refunds import refund_amount"
  ],
  "tests": [
    {
      "name": "test_unopened_item_refunds_full_price",
      "intent": "unopened item returns full price",
      "code": "# intent: unopened item returns full price\ndef test_unopened_item_refunds_full_price():\n    assert refund_amount(Decimal(\"80.00\"), opened=False) == Decimal(\"80.00\")\n"
    },
    {
      "name": "test_opened_item_keeps_restocking_fee",
      "intent": "opened item keeps 15% restocking fee",
      "code": "# intent: opened item keeps 15% restocking fee\ndef test_opened_item_keeps_restocking_fee():\n    assert refund_amount(Decimal(\"80.00\"), opened=True) == Decimal(\"68.00\")\n"
    },
    {
      "name": "test_unopened_free_item_refunds_zero",
      "intent": "unopened free item refunds zero",
      "code": "# intent: unopened free item refunds zero\ndef test_unopened_free_item_refunds_zero():\n    assert refund_amount(Decimal(\"0.00\"), opened=False) == Decimal(\"0.00\")\n"
    },
    {
      "name": "test_opened_free_item_refunds_zero",
      "intent": "opened free item refunds zero",
      "code": "# intent: opened free item refunds zero\ndef test_opened_free_item_refunds_zero():\n    assert refund_amount(Decimal(\"0.00\"), opened=True) == Decimal(\"0.00\")\n"
    },
    {
      "name": "test_negative_price_raises_value_error",
      "intent": "negative price raises ValueError",
      "code": "# intent: negative price raises ValueError\ndef test_negative_price_raises_value_error():\n    with pytest.raises(ValueError):\n        refund_amount(Decimal(\"-5.00\"), opened=False)\n"
    },
    {
      "name": "test_rounding_to_cents",
      "intent": "restocking fee is rounded to cents",
      "code": "# intent: restocking fee is rounded to cents\ndef test_rounding_to_cents():\n    # 15% of 10.00 is 1.50, no rounding needed; use a value that requires rounding\n    # 15% of 9.99 is 1.4985, rounded half up to 1.50\n    assert refund_amount(Decimal(\"9.99\"), opened=True) == Decimal(\"8.49\")\n"
    }
  ]
}
